package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.DeflaterOutputStream;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BZip2CompressorInputStream_read_TriageGen0Test {

    private byte[] createBzip2Data(String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (BZip2CompressorOutputStream bzOut = new BZip2CompressorOutputStream(baos)) {
            bzOut.write(content.getBytes(StandardCharsets.UTF_8));
        }
        return baos.toByteArray();
    }

    @Test
    public void testRead_NegativeOffs() throws IOException {
        byte[] data = createBzip2Data("test");
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(data))) {
            try {
                bis.read(new byte[10], -1, 5);
                Assert.fail("Expected IndexOutOfBoundsException for negative offs");
            } catch (IndexOutOfBoundsException e) {
                Assert.assertTrue(e.getMessage().contains("offs(-1) < 0."));
            }
        }
    }














}

