public class BZip2CompressorInputStream_read_TriageGen0Test {

    private byte[] createBzip2Data(String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (BZip2CompressorOutputStream bzOut = new BZip2CompressorOutputStream(baos)) {
            bzOut.write(content.getBytes(StandardCharsets.UTF_8));
        }
        return baos.toByteArray();
    }









    @Test
    public void testRead_SuccessPartial() throws IOException {
        String content = "Hello World";
        byte[] bzipData = createBzip2Data(content);
        byte[] expectedBytes = content.getBytes(StandardCharsets.UTF_8);

        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
