import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.DeflaterOutputStream;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BZip2CompressorInputStream_read_TriageGen0Test {

    private byte[] createBzip2Data(String content) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (BZip2CompressorOutputStream bzOut = new BZip2CompressorOutputStream(baos)) {
            bzOut.write(content.getBytes(StandardCharsets.UTF_8));
        }
        return baos.toByteArray();
    }











    @Test
    public void testRead_SuccessFullAndEOF() throws IOException {
        String content = "ABC";
        byte[] bzipData = createBzip2Data(content);
        byte[] expectedBytes = content.getBytes(StandardCharsets.UTF_8);

        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[10];
            int read = bis.read(dest, 0, 10);

            Assert.assertEquals(3, read);
            Assert.assertArrayEquals(expectedBytes, new byte[read]); // check content indirectly
            // manual check for accuracy
            Assert.assertEquals((byte)'A', dest[0]);
            Assert.assertEquals((byte)'B', dest[1]);
            Assert.assertEquals((byte)'C', dest[2]);

            int eofRead = bis.read(dest, 0, 1);
            Assert.assertEquals(-1, eofRead);
        }
    }




}

