        String content = "test";
        byte[] bzipData = createBzip2Data(content);

        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[5];
            // len 0 should return 0 (destOffs == offs, but loop condition destOffs < hi fails immediately)
